      oocScopes: list(src.oocScopes).filter(x => x && typeof x === 'object').map(x => ({ ...x, key: String(x.key || ''), scope: String(x.scope || 'main'), adopted: x.adopted === true, at: Number(x.at || 0), text: String(x.text || '').slice(0, 4000), ...(Object.hasOwn(x,'userId')?{userId:String(x.userId||'')}:{}), ...(Object.hasOwn(x,'assistantId')?{assistantId:String(x.assistantId||'')}:{}) })),
