    function choices() { try { const raw = GM_getValue(CHOICES_KEY, null); const o = typeof raw === 'string' ? JSON.parse(raw) : raw; return o && typeof o === 'object' && !Array.isArray(o) ? o : {}; } catch (_) { return {}; } }
