  function existing(r,c,task){if(newTask(task))return taskExisting(r,task);if(task==='currentItems')return '[현재상태.txt]\n'+String(r.slots.find(x=>x.id==='currentState')?.content||'')+'\n[중요물품.txt]\n'+ContinuumItems.get(r).filter(x=>!x.ended).map(x=>'- **'+x.title+'**\n'+x.content.split('\n').map(l=>'  '+l).join('\n')).join('\n\n');if(task==='logSummary')return String(r.slots.find(x=>x.id==='logSummary')?.content||'');return '[[WISH_PERSON_V1]]\n'+personRecords(r,c).map(({protected:_,coreId:__,...x})=>JSON.stringify(x)).join('\n')+'\n[[/WISH_PERSON_V1]]';}
