  async function source(r){const s=await prepareBulkSource(r,null,null),rows=[];let waiting=[];if(s.preface.length)rows.push({key:'prologue',assistantId:s.preface.at(-1).id,userText:'',assistantText:s.preface.map(x=>x.text).join('\n\n')});for(const turn of s.turns){const u=turn.messages.find(x=>x.role==='user'),a=turn.messages.filter(x=>x.role==='assistant');if(u)waiting.push(u);if(!a.length)continue;if(!waiting.length)throw Error('RP 순서를 확인할 수 없습니다.');rows.push({key:waiting.at(-1).id,assistantId:a.at(-1).id,userText:waiting.map(x=>x.text).join('\n\n'),assistantText:a.map(x=>x.text).join('\n\n'),shortcutUserParts:waiting.map(x=>x.text)});waiting=[];}if(waiting.length)throw Error('확정 답변이 없는 USER가 있습니다.');if(ContinuumShortcuts.on())ContinuumShortcuts.scan(r,rows);const selected=rows.filter(t=>!ContinuumScopeArchive.isExcludedTurn(r,t)&&!ContinuumShortcuts.excluded(r,t));if(!selected.length)throw Error('작업할 확정 RP가 없습니다.');return {...s,rows:selected,snapshot:s.messages.map(x=>[String(x.id),x.role,String(x.text),x.timeHints||[]])};}
  async function stamp(r,c,task){return {...(task==='lore'?{loreHash:await digest(packsOf(r))}:{}),roomId:r.chatId,apiChatId:String(apiChatIdOf(r)),rev:r._rev,epoch:r._epoch,restore:localRestoreEpoch,replay:ExternalReplay.revision(apiChatIdOf(r)),editRev:c.editRev||0,cogRev:c.rev||0,memoHash:await digest(ContinuumManager.active(r)),guideHash:guide(r,task).hash,domainHash:await digest(domain(r,c))};}
  function assertSource(current,expected,allow=false){if(!expected.length||current.length<expected.length||JSON.stringify(current.slice(0,expected.length))!==JSON.stringify(expected))throw Error('기존 RP가 수정·삭제·리롤·분기되었거나 순서가 바뀌었습니다. 다시 만드세요.');const appended=current.length-expected.length;if(appended&&!allow)throw Object.assign(Error('RP가 추가됐습니다. ‘추가된 RP는 다음 갱신으로 남기고 적용’을 선택하세요.'),{code:'RPCM_RP_APPENDED',appended});return appended;}
