        const duplicate=session.libraries.some(p=>String(p.ownerChatId)===String(target.chatId)&&(p.entries||[]).some(e=>{const o=e.copyOrigin;return o&&o.sourceRoomId===origin.sourceRoomId&&o.sourcePackId===origin.sourcePackId&&o.sourceEntryId===origin.sourceEntryId&&roomCopyEntryMeaning(normalizeLoreEntry(e))===meaning;}));
        if(duplicate){for(const p of session.libraries)if(String(p.ownerChatId)===String(target.chatId))checks[String(p.scopeId)]=copyFullStamp(p);skipped++;continue;}content.push(roomCopyLoreEntry(r.data,origin));
