      if(pack.entries.length!==expectedNormalizedCount)throw new Error(`${descriptor.origin}의 카드 ${expectedNormalizedCount}개 중 ${pack.entries.length}개만 정규화되어 일부만 가져오지 않았습니다. 중복 호칭 규칙과 카드 ID를 확인해 주세요.`);
