  async function loadLorePackCache(force = false) {
    if (lorePackCacheLoaded && !force) return lorePackCache;
    const all = await getAllCharacterLibraries();
    lorePackCache = all.filter(item => item?.kind === 'lore' || item?.format === 'wish-lore-pack').map(item => normalizeLorePack(item, item?.name || '자료집'));
    lorePackCacheLoaded = true;
    state.v2LorePacks = lorePackCache;
    state.v2LoreLoaded = true;
    return lorePackCache;
  }

  async function putLorePack(value, options = {}) {
    const pack = normalizeLorePack(value, value?.name || '자료집');
    pack.updatedAt = nowIso();
    await new Promise((resolve, reject) => {
      const tx = state.db.transaction(APP.libraryStoreName, 'readwrite');
      tx.objectStore(APP.libraryStoreName).put(pack);
      tx.oncomplete = resolve;
      tx.onerror = tx.onabort = () => reject(tx.error || new Error('자료집 저장 실패'));
    });
    const index = lorePackCache.findIndex(item => item.scopeId === pack.scopeId);
    if (index >= 0) lorePackCache[index] = pack; else lorePackCache.push(pack);
    state.v2LorePacks = lorePackCache;
    lorePackCacheLoaded = true;

    return pack;
  }

  function lorePackStorageFingerprint(value) {
    // IDB에서 실제로 읽은 원본 전체를 비교해 카드 본문뿐 아니라 entry id와 임베딩만 바뀐 경쟁 저장도 감지합니다.
    return JSON.stringify(value ?? null);
  }

  async function captureLorePackStorageFingerprints(packs,excludeScopeId='') {
    const rows=[];
    for(const pack of packs||[]){
      const id=String(pack?.scopeId||'');if(!id||id===String(excludeScopeId||''))continue;
      const raw=await getCharacterLibrary(id);
      if(!raw){const error=new Error(`사용 중인 자료집 ‘${pack?.name||id}’을 저장소에서 찾지 못했습니다.`);error.code='AUTO_LORE_STALE';throw error;}
      if(autoLoreContentFingerprint(raw)!==autoLoreContentFingerprint(pack)){const error=new Error(`사용 중인 자료집 ‘${pack?.name||id}’이 충돌 검사를 준비하는 동안 바뀌었습니다.`);error.code='AUTO_LORE_STALE';throw error;}
      rows.push([id,lorePackStorageFingerprint(raw)]);
    }
    return Object.fromEntries(rows);
  }

  async function putLorePackIfFingerprint(value, expectedStorageFingerprint, options = {}) {
    const pack = normalizeLorePack(value, value?.name || '자료집');
    pack.updatedAt = nowIso();
    await new Promise((resolve, reject) => {
      const tx = state.db.transaction(APP.libraryStoreName, 'readwrite');
      const store = tx.objectStore(APP.libraryStoreName);
      let rejected = false;
      const req = store.get(pack.scopeId);
      req.onsuccess = () => {
        const current = req.result;
        if (!current || lorePackStorageFingerprint(current) !== expectedStorageFingerprint) {
          rejected = true;
          const error = new Error('저장 직전에 자료팩이 다른 탭이나 작업에서 수정되어 오래된 결과를 덮어쓰지 않았습니다.');
          error.code = 'AUTO_LORE_STALE';
          try { tx.abort(); } catch (_) {}
          reject(error);
          return;
        }
        store.put(pack);
      };
      req.onerror = () => reject(req.error || new Error('자료집 확인 실패'));
      tx.oncomplete = () => resolve();
      tx.onerror = tx.onabort = () => { if (!rejected) reject(tx.error || new Error('자료집 저장 실패')); };
    });
    const index = lorePackCache.findIndex(item => item.scopeId === pack.scopeId);
    if (index >= 0) lorePackCache[index] = pack; else lorePackCache.push(pack);
    state.v2LorePacks = lorePackCache;
    lorePackCacheLoaded = true;

    return pack;
  }

