        if(gate)await recoverGenerationGate(rid,gate);
        if(ExternalReplay.pending(rid)||WishDisplayDrain.pending(rid)||unstartedRooms.has(room))return;
        if(!gate&&Date.now()<crackAuthState.retryAt)return;
