      const head=document.createElement('div');head.className='m3-panel-head c111-one-action';const title=document.createElement('b');title.textContent='파일·Koofr 백업';head.append(title,backup);section.append(head);const note=document.createElement('p');note.className='m3-muted';note.textContent='백업 파일 받기·올리기 · Koofr 연결';section.append(note);backupParent.replaceWith(section);
