  function c13People(){const m=c13Manager(),clashes=ContinuumManager.conflicts(c13Room());let html='<div class="m3-sechead c13-heading"><b>인지 5값</b>'+btn('추가','c13KnowledgeNew',{cls:'mini'})+'</div>';const groups=new Map();for(const k of m.knowledgeV1.filter(x=>!x.archived)){const key=k.key||'묶음 없음';(groups.get(key)||groups.set(key,[]).get(key)).push(k);}for(const [key,rows]of groups){html+='<div class="c13-group">'+esc(m.factGroups.find(x=>x.key===key)?.label||key)+'</div>';for(const k of rows){const clash=clashes.has(k.person.id+'\0'+k.fact.toLocaleLowerCase());html+=c13Row(k.person.name+' · '+ContinuumManager.LABELS[k.status],'<span class="c13-chip">'+esc(ContinuumManager.LABELS[k.status])+'</span><p>'+esc(k.fact)+'</p>'+(k.actualFact?c13Small('객관적 사실: '+k.actualFact):'')+(clash?'<p class="c13-warning">충돌 · 같은 인물과 사실에 다른 상태가 있어 주입하지 않아요.</p>':'')+c13Small('코어 투영: '+({knows:'알고 있음','does-not-know':'모름',suspects:'의심 중',mistaken:'모름',unconfirmed:'미등록'})[k.status]),btn('편집','c13KnowledgeEdit',{arg:k.id,cls:'mini'}),'c13-k-'+k.id);}}return html+(groups.size?'':c13Small('등록된 인지 5값이 없습니다. 코어 인지 화면은 아래에서 계속 편집할 수 있어요.'));}
