 shortcutUnstory:async arg=>{const [id,key]=String(arg).split('|'),d=WUI.ui.dlg(id);if(!d||d.busy)return;const room=wishShortcutRoom(d);d.busy=true;WUI.paint();try{await ContinuumShortcuts.setAdopted(room,key,false,'kept');notify('다시 뺐습니다. 이미 정리된 기억은 지우지 않습니다.','success',5000);}finally{d.busy=false;await wishShortcutReload(d);}},
