 shortcutCopy:async arg=>{const [id,key]=String(arg).split('|'),d=WUI.ui.dlg(id);if(!d)return;const r=wishShortcutRow(d,key);await copyPlainText(r.assistantText||'');notify('답변 원문을 복사했습니다.','success');},
 shortcutAdopt:async arg=>{const [id,key,flag]=String(arg).split('|'),d=WUI.ui.dlg(id);if(!d||d.busy)return;const room=wishShortcutRoom(d),r=(d.excluded||[]).find(x=>x.key===key);if(!r)return;d.busy=true;WUI.paint();try{await ContinuumShortcuts.setAdopted(room,key,flag==='1',flag==='1'?'story':'kept',r.shortcutId);notify(flag==='1'?'기억에 넣었습니다. 다음 기억 정리부터 입력에 들어갑니다.':'다시 뺐습니다. 이미 정리된 기억은 지우지 않습니다.','success');}finally{d.busy=false;await wishShortcutReload(d);}},
