// continuum.5: 보관함 시트 도우미 — 대화 기록을 다시 읽어 목록을 채운다(원문은 저장하지 않음)
async function wishShortcutReload(d){
 const room=d.room;d.loading=true;d.error='';WUI.paint();
 try{const frame=stableFrame(await fetchRecentMessages(apiChatIdOf(room),Math.max(50,Number(loadAiSettings().maxMessages)||100)));
  if(state.currentRoom!==room)throw Error('방이 바뀌었어요. 보관함을 다시 열어 주세요.');
  d.frame=frame;d.rows=ContinuumShortcuts.archiveRows(room,frame);d.excluded=ContinuumShortcuts.excludedRows(room,frame);}
 catch(e){d.error=String(e?.message||e);}
 finally{d.loading=false;if(WUI.ui.dlg(d.id)===d)WUI.paint();}
 return d;
}
function wishShortcutRoom(d){if(!state.currentRoom||String(d.room?.chatId)!==String(state.currentRoom.chatId))throw Error('방이 바뀌었어요. 보관함을 다시 열어 주세요.');return state.currentRoom;}
function wishShortcutRow(d,key){const r=(d.rows||[]).find(x=>x.key===key);if(!r)throw Error('보관한 턴을 찾지 못했어요.');if(r.missing)throw Error('크랙에서 지워진 메시지라 원문이 없어요.');return r;}
function wishShortcutPicked(d){return Object.entries(d.draft.pick||{}).filter(([,v])=>v).map(([k])=>decodeURIComponent(k)).filter(k=>(d.rows||[]).some(x=>x.key===k&&!x.missing));}
// 자료 카드로 넣기: 이미 카드로 넣은 턴이면 묻고(다시 만들면 기존 카드를 바꿈) → 미리 보기(AI 초안 또는 원문) → 저장. 여러 턴은 차례로.
async function wishShortcutCardStart(d,keys){
 const room=wishShortcutRoom(d),[key,...rest]=keys,r=wishShortcutRow(d,key);
 if(ContinuumShortcuts.cardExists(room,key)&&!d.confirmed?.[key]){WUI.openSheet('confirm',{title:'이미 카드로 넣었어요',body:'「'+(r.title||r.name)+'」 카드를 다시 만들까요? 다시 만들면 기존 카드를 바꿉니다(새로 늘리지 않음).',okLabel:'다시 만들기',danger:false,fn:()=>{d.confirmed||={};d.confirmed[key]=true;return wishShortcutCardStart(d,keys);}});return null;}
 const raw=ContinuumShortcuts.rawCard(r),fill=(p,c,ai)=>{p.draft={name:c.name,type:c.type,triggers:(c.triggers||[]).join(', '),full:c.full,compact:c.compact,micro:c.micro};p.ai=ai;p.truncated=!!c.truncated;};
 const p=WUI.openSheet('shortcutCardPreview',{room,key,row:r,parentId:d.id,queue:rest,ai:false,truncated:false,busy:false,error:'',draft:{name:'',type:'other',triggers:'',full:'',compact:'',micro:''}});
 fill(p,raw,false);WUI.paint();
 return p;
}
// continuum.5: 확인 탭 「이 방의 크랙 단축어」 선택칸(처리 방식 · 넣는 곳). 방 데이터에 저장하고 공통 기록(id → 선택값)에도 적는다.
WUI_ADAPTER.bind['continuumShortcut']=async(value,sub)=>{
 const room=state.currentRoom;if(!room)return;const [id,field]=String(sub||'').split('|');
 if(field==='mode'){await ContinuumShortcuts.setMode(room,id,String(value));notify('「'+(ContinuumShortcuts.peek(room)?.rows?.[id]?.name||id.slice(0,6))+'」 처리 방식: '+ContinuumShortcuts.MODES[String(value)]+' · 다음 기억 정리부터 적용됩니다.','success');}
 else if(field==='archiveTo'){await ContinuumShortcuts.setArchiveTo(room,id,String(value));}
};
// 이 방 · 임베딩 모델 (AGENTS 규칙 6): 바꾸면 질의 벡터 캐시를 비우고, 카드·로그 벡터는 모델명 불일치로 다음 준비 때 다시 만든다.
WUI_ADAPTER.bind['continuumRoom.embeddingModel']=async value=>{
 const room=state.currentRoom;if(!room)return;const next=String(value||'').trim()||APP.loreEmbeddingModel;if(next===room.loreConfig.embeddingModel)return;
 const before=room.loreConfig.embeddingModel;room.loreConfig.embeddingModel=next;continuumRoomState(room).embeddingIssue=null;
 try{await saveRoom(room);}catch(e){room.loreConfig.embeddingModel=before;throw e;}
 LORE_QUERY_VECTOR_CACHE.clear();allFitRankCache.clear();
 notify('임베딩 모델을 '+next+'(으)로 바꿨습니다. 저장된 벡터는 다음 의미 검색 준비에서 이 모델로 다시 만듭니다.','success',5000);
};
